function calOut(array $data, int $status=200): never { http_response_code($status); echo json_encode($data, JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE); exit; }
function calBody(): array { $raw=file_get_contents('php://input'); if($raw===false||trim($raw)==='') return $_POST?:[]; $d=json_decode($raw,true); return is_array($d)?$d:[]; }
function calUserId(): ?int { if(function_exists('getCurrentUserId')){$id=getCurrentUserId();return $id?(int)$id:null;} return !empty($_SESSION['user_id'])?(int)$_SESSION['user_id']:null; }
function calJson(?string $value, array $fallback=[]): array { $d=$value!==null?json_decode($value,true):null; return is_array($d)?$d:$fallback; }
function calDate(string $value, string $label): string { $d=DateTimeImmutable::createFromFormat('!Y-m-d',$value); if(!$d||$d->format('Y-m-d')!==$value) throw new InvalidArgumentException("Select a valid {$label}."); return $value; }
function calEnv(array $names): string { foreach($names as $n){$v=getenv($n);if(is_string($v)&&trim($v)!=='')return trim($v);} return ''; }
function calGoogleConfig(): array {
