    $secret=calEnv(['SMS2_GOOGLE_CALENDAR_CLIENT_SECRET','GOOGLE_CALENDAR_CLIENT_SECRET']);
    $redirect=calEnv(['SMS2_GOOGLE_CALENDAR_REDIRECT_URI','GOOGLE_CALENDAR_REDIRECT_URI']);
    if($redirect===''){$scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';$host=(string)($_SERVER['HTTP_HOST']??'localhost');$base=preg_match('#^https?://#i',BASE_URL)?BASE_URL:$scheme.'://'.$host.'/'.ltrim(BASE_URL,'/');$redirect=rtrim($base,'/').'/api/scheduling/calendar.php?action=google_callback';}
    return ['client_id'=>$client,'client_secret'=>$secret,'redirect_uri'=>$redirect,'configured'=>$client!==''&&$secret!==''];
}
function calHistory(PDO $pdo,int $id,string $action,?string $from,?string $to,string $detail,array $meta=[]):void{
    $st=$pdo->prepare('INSERT INTO calendar_integration_history(integration_id,action,from_status,to_status,detail,metadata_json,changed_by) VALUES(?,?,?,?,?,?,?)');
    $st->execute([$id,$action,$from,$to,substr($detail,0,500),$meta?json_encode($meta,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE):null,calUserId()]);
}
function calScheduleCatalog(PDO $pdo):array{
    $out=[];
    $rows=$pdo->query("SELECT academic_year,semester,COUNT(*) event_count,COUNT(DISTINCT section_id) section_count,MIN(updated_at) first_updated,MAX(updated_at) last_updated FROM schedule_entries WHERE status='Published' AND academic_year IS NOT NULL AND semester IS NOT NULL GROUP BY academic_year,semester ORDER BY academic_year DESC,semester")->fetchAll();
    foreach($rows as $r){$key='regular:'.rawurlencode($r['academic_year']).':'.rawurlencode($r['semester']);$out[]=['key'=>$key,'type'=>'Regular','title'=>'Published Class Schedule','academic_year'=>$r['academic_year'],'semester'=>$r['semester'],'date_from'=>date('Y-m-d'),'date_to'=>date('Y-m-d',strtotime('+120 days')),'entry_count'=>(int)$r['event_count'],'scope'=>(int)$r['section_count'].' section(s)','status'=>'Published'];}
    $rows=$pdo->query("SELECT academic_year,semester,COUNT(*) event_count,MIN(class_date) date_from,MAX(class_date) date_to FROM special_classes WHERE status='Published' GROUP BY academic_year,semester ORDER BY academic_year DESC,semester")->fetchAll();
    foreach($rows as $r){$out[]=['key'=>'special:'.rawurlencode((string)$r['academic_year']).':'.rawurlencode((string)$r['semester']),'type'=>'Special','title'=>'Published Special Classes','academic_year'=>$r['academic_year'],'semester'=>$r['semester'],'date_from'=>$r['date_from'],'date_to'=>$r['date_to'],'entry_count'=>(int)$r['event_count'],'scope'=>'Special class schedule','status'=>'Published'];}
    $rows=$pdo->query("SELECT b.id,b.title,b.exam_type,b.academic_year,b.semester,b.date_from,b.date_to,COUNT(e.id) event_count FROM exam_timetable_batches b JOIN exam_schedules e ON e.batch_id=b.id AND e.status='Published' WHERE b.status='Published' GROUP BY b.id ORDER BY b.date_from DESC,b.id DESC")->fetchAll();
    foreach($rows as $r){$out[]=['key'=>'exam:'.$r['id'],'type'=>'Exam','title'=>$r['title'],'academic_year'=>$r['academic_year'],'semester'=>$r['semester'],'date_from'=>$r['date_from'],'date_to'=>$r['date_to'],'entry_count'=>(int)$r['event_count'],'scope'=>$r['exam_type'].' examinations','status'=>'Published'];}
    return $out;
}
function calFindSchedule(PDO $pdo,string $key):array{
    foreach(calScheduleCatalog($pdo) as $s) if(hash_equals($s['key'],$key)) return $s;
    throw new RuntimeException('The selected schedule is no longer published. Return to Published Schedule, validate it, and publish it before exporting.');
}
function calRecipients(PDO $pdo):array{
    $out=['Teacher'=>[],'Section'=>[],'Program'=>[],'Room'=>[]];
    foreach($pdo->query("SELECT id,full_name,email,department FROM teachers WHERE status='Active' ORDER BY full_name") as $r)$out['Teacher'][]=['key'=>'Teacher:'.$r['id'],'label'=>$r['full_name'],'detail'=>trim(($r['department']?:'Faculty').($r['email']?' · '.$r['email']:''))];
    foreach($pdo->query("SELECT id,code,name,program FROM sections WHERE status='Active' ORDER BY code") as $r)$out['Section'][]=['key'=>'Section:'.$r['id'],'label'=>$r['code'],'detail'=>$r['program'].' · '.$r['name']];
    foreach($pdo->query("SELECT DISTINCT program FROM sections WHERE status='Active' AND program<>'' ORDER BY program") as $r)$out['Program'][]=['key'=>'Program:'.$r['program'],'label'=>$r['program'],'detail'=>'All published events for this program'];
    foreach($pdo->query("SELECT id,room_code,building,capacity FROM rooms WHERE status<>'Maintenance' ORDER BY room_code") as $r)$out['Room'][]=['key'=>'Room:'.$r['id'],'label'=>$r['room_code'],'detail'=>trim(($r['building']?:'Campus').' · '.$r['capacity'].' seats')];
    return $out;
}
function calRecipientMatch(array $row,array $keys):bool{
    if(!$keys)return true;
    foreach($keys as $key){[$type,$value]=array_pad(explode(':',(string)$key,2),2,'');if($type==='Teacher'&&(string)($row['teacher_id']??'')===$value)return true;if($type==='Section'&&(string)($row['section_id']??'')===$value)return true;if($type==='Room'&&(string)($row['room_id']??'')===$value)return true;if($type==='Program'&&(string)($row['program']??'')===$value)return true;}
    return false;
}
function calEvent(array $row,string $source,int $sourceId,string $date,array $settings):array{
    $tz=(string)($settings['timezone']??'Asia/Manila'); try{$zone=new DateTimeZone($tz);}catch(Throwable){$tz='Asia/Manila';$zone=new DateTimeZone($tz);}
    $start=(new DateTimeImmutable($date.' '.substr((string)$row['start_time'],0,8),$zone))->format(DateTimeInterface::ATOM);
    $end=(new DateTimeImmutable($date.' '.substr((string)$row['end_time'],0,8),$zone))->format(DateTimeInterface::ATOM);
    $subject=trim((string)($row['subject_code']??'').' — '.(string)($row['subject_name']??''),' —');
    if($source==='Special')$subject=(string)$row['source_title'];
    if($source==='Exam')$subject=(string)$row['exam_type'].' Exam — '.$subject;
    $summary=$subject; if(!empty($settings['include_section'])&&!empty($row['section_code']))$summary.=' · '.$row['section_code'];
    $parts=[]; if(!empty($settings['include_subject']))$parts[]='Subject: '.$subject;if(!empty($settings['include_section'])&&!empty($row['section_code']))$parts[]='Section: '.$row['section_code'];if(!empty($settings['include_faculty'])&&!empty($row['teacher_name']))$parts[]='Faculty: '.$row['teacher_name'];if(!empty($settings['include_room'])&&!empty($row['room_code']))$parts[]='Room: '.$row['room_code'];if(!empty($settings['include_class_type'])&&!empty($row['class_type']))$parts[]='Type: '.$row['class_type'];if(!empty($settings['include_description'])&&!empty($row['remarks']))$parts[]=(string)$row['remarks'];
    $key=hash('sha256',$source.'|'.$sourceId.'|'.$date.'|'.$start.'|'.$end);
    $event=['event_key'=>$key,'source'=>$source,'source_id'=>$sourceId,'date'=>$date,'start'=>$start,'end'=>$end,'start_time'=>substr((string)$row['start_time'],0,5),'end_time'=>substr((string)$row['end_time'],0,5),'summary'=>$summary,'description'=>implode("\n",$parts),'location'=>!empty($settings['include_room'])?(string)($row['room_code']??''):'','section_code'=>(string)($row['section_code']??''),'teacher_name'=>(string)($row['teacher_name']??''),'room_code'=>(string)($row['room_code']??''),'timezone'=>$tz,'color'=>(string)($settings['color']??'#1769e0')];
    $event['content_hash']=hash('sha256',json_encode($event,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)); return $event;
}
function calCollectEvents(PDO $pdo,array $schedule,string $from,string $to,array $keys,array $settings):array{
    if($from>$to)throw new InvalidArgumentException('Start date must not be later than end date.');
    $events=[];$type=$schedule['type'];
    if($type==='Regular'){
        $st=$pdo->prepare("SELECT se.*,s.code section_code,s.program,sub.code subject_code,sub.name subject_name,t.full_name teacher_name,r.room_code FROM schedule_entries se JOIN sections s ON s.id=se.section_id JOIN subjects sub ON sub.id=se.subject_id LEFT JOIN teachers t ON t.id=se.teacher_id LEFT JOIN rooms r ON r.id=se.room_id WHERE se.status='Published' AND se.academic_year=? AND se.semester=?");$st->execute([$schedule['academic_year'],$schedule['semester']]);$rows=$st->fetchAll();
        $sub=$pdo->prepare("SELECT sa.schedule_entry_id,sa.absence_date,st.full_name substitute_name FROM substitute_assignments sa JOIN teachers st ON st.id=sa.substitute_teacher_id WHERE sa.status IN ('Assigned','Ongoing','Completed') AND sa.absence_date BETWEEN ? AND ?");$sub->execute([$from,$to]);$subs=[];foreach($sub as $x)$subs[$x['schedule_entry_id'].'|'.$x['absence_date']]=$x['substitute_name'];
        for($cursor=new DateTimeImmutable($from);$cursor<=new DateTimeImmutable($to);$cursor=$cursor->modify('+1 day')){$date=$cursor->format('Y-m-d');$day=$cursor->format('l');foreach($rows as $r){if($r['day_of_week']!==$day||!calRecipientMatch($r,$keys))continue;$k=$r['id'].'|'.$date;if(isset($subs[$k])){$r['teacher_name']=$subs[$k];$r['remarks']=trim((string)$r['remarks'].' Substitute faculty assignment.');}$events[]=calEvent($r,'Class',(int)$r['id'],$date,$settings);}}
    }elseif($type==='Special'){
        $st=$pdo->prepare("SELECT sc.*,s.code section_code,s.program,sub.code subject_code,sub.name subject_name,t.full_name teacher_name,r.room_code,sc.title source_title,sc.special_type class_type FROM special_classes sc LEFT JOIN sections s ON s.id=sc.section_id LEFT JOIN subjects sub ON sub.id=sc.subject_id LEFT JOIN teachers t ON t.id=sc.teacher_id LEFT JOIN rooms r ON r.id=sc.room_id WHERE sc.status='Published' AND sc.academic_year=? AND sc.semester=? AND sc.class_date BETWEEN ? AND ?");$st->execute([$schedule['academic_year'],$schedule['semester'],$from,$to]);foreach($st as $r)if(calRecipientMatch($r,$keys))$events[]=calEvent($r,'Special',(int)$r['id'],$r['class_date'],$settings);
    }else{
        $batch=(int)substr($schedule['key'],5);$st=$pdo->prepare("SELECT e.*,s.code section_code,s.program,sub.code subject_code,sub.name subject_name,t.full_name teacher_name,r.room_code,'Exam' class_type FROM exam_schedules e JOIN sections s ON s.id=e.section_id JOIN subjects sub ON sub.id=e.subject_id LEFT JOIN teachers t ON t.id=e.proctor_id LEFT JOIN rooms r ON r.id=e.room_id WHERE e.status='Published' AND e.batch_id=? AND e.exam_date BETWEEN ? AND ?");$st->execute([$batch,$from,$to]);foreach($st as $r)if(calRecipientMatch($r,$keys))$events[]=calEvent($r,'Exam',(int)$r['id'],$r['exam_date'],$settings);
    }
    usort($events,fn($a,$b)=>[$a['date'],$a['start_time'],$a['summary']]<=>[$b['date'],$b['start_time'],$b['summary']]); return $events;
}
function calPayload(PDO $pdo,array $p):array{
    $key=trim((string)($p['schedule_key']??''));$schedule=calFindSchedule($pdo,$key);$from=calDate((string)($p['date_from']??$schedule['date_from']),'start date');$to=calDate((string)($p['date_to']??$schedule['date_to']),'end date');
    if($from>$to)throw new InvalidArgumentException('Start date must not be later than end date.');if((new DateTimeImmutable($from))->diff(new DateTimeImmutable($to))->days>370)throw new InvalidArgumentException('Choose a date range of 370 days or fewer.');
    $method=(string)($p['method']??'ICS');if(!in_array($method,['ICS','Google'],true))throw new InvalidArgumentException('Select ICS Export or Google Calendar.');
    $name=trim((string)($p['name']??''));if($name==='')throw new InvalidArgumentException('Calendar name is required.');if(mb_strlen($name)>150)throw new InvalidArgumentException('Calendar name must be 150 characters or fewer.');
