function calIntegration(PDO $pdo,int $id):array{
    $st=$pdo->prepare("SELECT ci.*,COALESCE(u.full_name,u.username,'System') created_by_name FROM calendar_integrations ci LEFT JOIN users u ON u.id=ci.created_by WHERE ci.id=?");$st->execute([$id]);$r=$st->fetch();if(!$r)throw new RuntimeException('Calendar integration was not found.');unset($r['access_token_encrypted'],$r['refresh_token_encrypted']);$r['recipient_keys']=calJson($r['recipient_keys_json']);$r['settings']=calJson($r['settings_json']);unset($r['recipient_keys_json'],$r['settings_json']);return $r;
}
function calList(PDO $pdo):array{
    $rows=$pdo->query("SELECT ci.id,ci.reference_no,ci.name,ci.method,ci.schedule_type,ci.academic_year,ci.semester,ci.status,ci.event_count,ci.google_account_email,ci.last_sync_at,ci.last_error,ci.updated_at,COALESCE(u.full_name,u.username,'System') created_by_name FROM calendar_integrations ci LEFT JOIN users u ON u.id=ci.created_by ORDER BY ci.updated_at DESC,ci.id DESC")->fetchAll();$stats=['total'=>count($rows),'synced'=>0,'pending'=>0,'failed'=>0];foreach($rows as $r){if($r['status']==='Synced')$stats['synced']++;elseif($r['status']==='Failed')$stats['failed']++;else$stats['pending']++;}return [$rows,$stats];
