function calIcsEscape(string $v):string{return str_replace(["\\",";",",","\r\n","\r","\n"],["\\\\","\\;","\\,","\\n","\\n","\\n"],$v);}
function calIcs(array $integration,array $events):string{
    $lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Bestlink College//SMS2 Calendar Integration//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH','X-WR-CALNAME:'.calIcsEscape($integration['name'])];
